Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include<vector>
#include<string>
#include<algorithm>
#include<iostream>
#include <iomanip>
#include<cmath>
#include<cstdlib>
#include<cstdio>
#include<stack>
#include<queue>
#include<cstring>
#include<map>
#include<set>
using namespace std;
#define MOD 1000000007
int a[1111111];
long long x[30];
long long now=6;
int cal(long long n)
{
	int l=0;
	if(n<0)
		n=-n;
	if(n<=now)
		return a[n];
	long long last;
	long long t=n;
	while(t>0)
	{
		l++;
		last=t;
		t/=10;
	}
	if(last<=5)
	{
		if(n>=x[l]*last||last==1)
			return cal(n-x[l]*last)+last*l;
		else
		{
			int r1,r2;
			r1=cal(x[l]*last-n)+last*l;
			r2=cal(n-x[l]*(last-1))+(last-1)*l;
			return min(r1,r2);
		}
	}
	else if(last>6)
		return cal(x[l+1]-n)+l+1;
	else
	{
		int r1,r2;
		if(n>x[l]*last)
			r1=cal(n-x[l]*last)+last*l;
		else
			r1=cal(x[l]*last-n)+last*l;
		r2=cal(n-x[l]*(last-1))+(last-1)*l;
		r1=min(r1,r2);
		r2=cal(x[l+1]-n)+l+1;
		return min(r1,r2);
	}
}
int main()
{
	int i;
	long long n;
	cin>>n;
	x[1]=1;
	for(i=2;i<=15;i++)
	{
		x[i]=x[i-1]*10+1;
	}
	for(i=0;i<7;i++)
		a[i]=i;
	for(i=7;i<1111110;i++)
	{
		a[i]=cal(i);
		now=i;
	}
	if(n<1111110)
		cout<<a[n]<<endl;
	else
	{
		cout<<cal(n)<<endl;
	}
	//system("pause");
    return 0;
}
